#!/usr/bin/env python3
"""Apply the layer-3 closer's registry change (MESHSAT-1357, 27 September 2026) BY RECORD ID, with asserted
old text, to v2/ecad/tools/pcb_requirements.yaml (and, unless --skip-files, the CFL-003 and CFL-006 source fixes of
pcb_board_facts.yaml, pcb_pack_protection.yaml and pcb_energy_chain.yaml). Idempotent: a second run changes nothing.

Generated by drafts/hc3/author.py from the registry at e3aedb25; do not edit by hand.

It also files the four documents the new pass lines cite (drafts/hc3/vendor/, sha256 checked) and appends the
SOURCES.yaml blocks of the layer-1 and layer-3 closers (documents_filed_hc1, documents_filed_hc3), which is step 0
of fnd/hc1's apply_hc1_registry.py: run THIS script instead of that one (--no-install skips the filing).

Order at integration (drafts/hc3/README.md): merge the other branches and commit the merged documents first, so
the re-anchoring can name that commit; run this from the repository root with --dry-run; read what it reports;
run it; then `python3 rules_lib.py requirements` and `python3 rules_render.py --requirements` in v2/ecad/tools.
New ids (SC, S, REQ, CON, CFL) are taken from the next free number at apply time; a block already present (found
by its own text) keeps its id."""
import re
import subprocess
import difflib
import hashlib
import os


SECTIONS = ("owner_rulings", "session_choices", "open_items", "closed_items", "records")


def norm(s):
    return " ".join(str(s or "").split())


class Refused(Exception):
    pass


class Doc:
    def __init__(self, text):
        self.lines = text.split("\n")

    def text(self):
        return "\n".join(self.lines)

    # ---- structure
    def section_range(self, name):
        start = None
        for i, l in enumerate(self.lines):
            if l.startswith(name + ":"):
                start = i
                break
        if start is None:
            raise Refused("no top-level section %s" % name)
        end = len(self.lines)
        for j in range(start + 1, len(self.lines)):
            l = self.lines[j]
            if l and not l.startswith(" ") and not l.startswith("#"):
                end = j
                break
        # a comment block that introduces the NEXT section belongs to it, not to this one
        while end > start + 1 and (self.lines[end - 1].startswith("#") or not self.lines[end - 1].strip()):
            end -= 1
        return start, end

    def blocks(self, section):
        s, e = self.section_range(section)
        out, cur = [], None
        for i in range(s + 1, e):
            m = re.match(r"^  - id: (\S+)\s*$", self.lines[i])
            if m:
                if cur:
                    out.append(cur)
                cur = [m.group(1).strip('"'), i, i + 1]
            elif cur:
                cur[2] = i + 1
        if cur:
            out.append(cur)
        res = []
        for bid, bs, be in out:
            while be > bs + 1 and not self.lines[be - 1].strip():
                be -= 1
            res.append((bid, bs, be))
        return res

    def ids(self, section):
        return [b[0] for b in self.blocks(section)]

    def block(self, section, bid):
        for b in self.blocks(section):
            if b[0] == bid:
                return b
        raise Refused("%s: no block %s" % (section, bid))

    def has(self, section, bid):
        return bid in self.ids(section)

    def block_text(self, section, bid):
        _, bs, be = self.block(section, bid)
        return "\n".join(self.lines[bs:be])

    def field_range(self, section, bid, field):
        """(first line, end line) of `field` at record indent (4 spaces), or None."""
        _, bs, be = self.block(section, bid)
        for i in range(bs, be):
            l = self.lines[i]
            if i == bs:
                key = l[4:]                                   # "  - id: X"
            elif l.startswith("    ") and not l.startswith("     "):
                key = l[4:]
            else:
                key = None
            if key is not None and re.match(r"^%s:(\s|$)" % re.escape(field), key):
                j = i + 1
                while j < be:
                    lj = self.lines[j]
                    if lj.startswith("    ") and not lj.startswith("     ") and re.match(r"^    [A-Za-z_][A-Za-z0-9_]*:", lj):
                        break
                    if not lj.strip():
                        # a blank line inside a folded value is part of it only if a deeper line follows
                        k = j
                        while k < be and not self.lines[k].strip():
                            k += 1
                        if k >= be or not self.lines[k].startswith("      "):
                            break
                    j += 1
                return i, j
        return None

    def get_field(self, section, bid, field):
        r = self.field_range(section, bid, field)
        if r is None:
            return None
        return "\n".join(self.lines[r[0]:r[1]])

    # ---- operations
    def set_field(self, section, bid, field, old, new, after=None):
        """Replace the whole text of `field` (as written, key line included). old None = the field must be absent
        (then it is inserted after field `after`, or at the block's end); new None = remove it."""
        cur = self.get_field(section, bid, field)
        if norm(cur) == norm(new):
            return "skip"
        if (cur is None and old is None) or (cur is not None and old is not None and norm(cur) == norm(old)):
            r = self.field_range(section, bid, field)
            new_lines = [] if new is None else new.split("\n")
            if r is None:
                if after:
                    ar = self.field_range(section, bid, after)
                    if ar is None:
                        raise Refused("%s %s: cannot insert %s after absent field %s" % (section, bid, field, after))
                    pos = ar[1]
                else:
                    pos = self.block(section, bid)[2]
                self.lines[pos:pos] = new_lines
            else:
                self.lines[r[0]:r[1]] = new_lines
            return "applied"
        raise Refused("%s %s field %s: expected\n  OLD: %s\nor\n  NEW: %s\nfound\n  NOW: %s"
                      % (section, bid, field, norm(old)[:400], norm(new)[:400], norm(cur)[:400]))

    def replace_in_field(self, section, bid, field, old_sub, new_sub):
        """Replace one exact substring inside a field (whitespace-normalised match on the field, exact on the text)."""
        cur = self.get_field(section, bid, field)
        if cur is None:
            raise Refused("%s %s: no field %s" % (section, bid, field))
        if norm(new_sub) and norm(new_sub) in norm(cur) and norm(old_sub) not in norm(cur):
            return "skip"
        if cur.count(old_sub) != 1:
            raise Refused("%s %s field %s: the old text occurs %d times, expected once: %r"
                          % (section, bid, field, cur.count(old_sub), old_sub[:200]))
        r = self.field_range(section, bid, field)
        self.lines[r[0]:r[1]] = cur.replace(old_sub, new_sub).split("\n")
        return "applied"

    def append_list_item(self, section, bid, field, item_text, fingerprint):
        """Append a list item (its full indented text) to a list field unless an item carrying `fingerprint` is there."""
        cur = self.get_field(section, bid, field)
        if cur is None:
            raise Refused("%s %s: no list field %s" % (section, bid, field))
        if norm(fingerprint) in norm(cur):
            return "skip"
        r = self.field_range(section, bid, field)
        self.lines[r[1]:r[1]] = item_text.split("\n")
        return "applied"

    def add_block(self, section, text, after=None, fingerprint=None):
        """Insert a block (starting '  - id: X'), after block `after` or at the section's end, unless a block carrying
        `fingerprint` (or the same id) is already in the section."""
        bid = re.match(r"^  - id: (\S+)", text).group(1)
        for b in self.blocks(section):
            bt = "\n".join(self.lines[b[1]:b[2]])
            if b[0] == bid or (fingerprint and norm(fingerprint) in norm(bt)):
                return "skip"
        if after:
            pos = self.block(section, after)[2]
        else:
            bl = self.blocks(section)
            pos = bl[-1][2] if bl else self.section_range(section)[0] + 1
        sep = [""] if section == "records" else []
        self.lines[pos:pos] = sep + text.rstrip("\n").split("\n")
        return "applied"

    def remove_block(self, section, bid, must_contain):
        if not self.has(section, bid):
            return "skip"
        _, bs, be = self.block(section, bid)
        bt = "\n".join(self.lines[bs:be])
        if norm(must_contain) not in norm(bt):
            raise Refused("%s %s: refusing to remove, it no longer says %r" % (section, bid, must_contain[:120]))
        # drop a blank separator line before a record block
        if section == "records" and bs > 0 and not self.lines[bs - 1].strip():
            bs -= 1
        del self.lines[bs:be]
        return "applied"

    def set_top(self, key, old, new):
        for i, l in enumerate(self.lines):
            if l.startswith(key + ":"):
                cur = l[len(key) + 1:].strip()
                if cur == new:
                    return "skip"
                if old is not None and cur != old:
                    raise Refused("top %s: expected %s or %s, found %s" % (key, old, new, cur))
                self.lines[i] = "%s: %s" % (key, new)
                return "applied"
        raise Refused("no top-level key %s" % key)

    def replace_text(self, old, new):
        """A unique substring of the whole file (the header comment)."""
        t = self.text()
        if new in t:
            return "skip"
        if t.count(old) != 1:
            raise Refused("header text occurs %d times, expected once: %r" % (t.count(old), old[:120]))
        self.lines = t.replace(old, new).split("\n")
        return "applied"

    # ---- ids
    def max_id(self, prefix):
        pat = re.compile(r"\b%s-(\d+)\b" % re.escape(prefix))
        return max([int(m.group(1)) for m in pat.finditer(self.text())] or [0])


# ---- citation re-anchoring (file:line in `source` entries) ------------------------------------------------------
CITE = re.compile(r"(v2/[^\s:,;()\"']+\.(?:md|py|yaml|json|txt|net|tsv)):(\d+)(?:-(\d+))?")


def git_show(root, commit, path):
    r = subprocess.run(["git", "-C", root, "show", "%s:%s" % (commit, path)], capture_output=True, text=True)
    return r.stdout.split("\n") if r.returncode == 0 else None


def line_map(old, new):
    sm = difflib.SequenceMatcher(None, old, new, autojunk=False)
    m = {}
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        if tag == "equal":
            for k in range(i2 - i1):
                m[i1 + k] = j1 + k
    return m


def map_citation(old, new, lmap, a, b):
    """Map 1-based lines a..b of `old` into `new`. (a', b', how) or (None, None, reason)."""
    idx = list(range(a - 1, b))
    if all(i in lmap for i in idx) and all(lmap[idx[k]] == lmap[idx[0]] + k for k in range(len(idx))):
        return lmap[idx[0]] + 1, lmap[idx[-1]] + 1, "moved" if lmap[idx[0]] != idx[0] else "same"
    block = old[a - 1:b]
    if block and any(x.strip() for x in block):
        hits = [j for j in range(len(new) - len(block) + 1) if new[j:j + len(block)] == block]
        if len(hits) == 1:
            return hits[0] + 1, hits[0] + len(block), "found"
    # The cited text was rewritten where it stood: anchor on the nearest unchanged line before and after the range and
    # carry the range between them. This is a POSITIONAL mapping, so the caller reports it for a hand re-read.
    before = [i for i in lmap if i < a - 1]
    after = [i for i in lmap if i > b - 1]
    if before and after:
        pa, pb = max(before), min(after)
        na = lmap[pa] + (a - 1 - pa)
        nb = lmap[pb] - (pb - (b - 1))
        if lmap[pa] < na <= nb < lmap[pb] or (na == nb and lmap[pa] < na < lmap[pb]):
            return na + 1, nb + 1, "rewritten in place"
    return None, None, "text changed"


def reanchor_source_entry(s, root, from_commit, files_old, files_new, maps, historical=False):
    """Re-anchor every file:line in one source string. Returns (new string, list of (path, a, b, how)). In a
    HISTORICAL record (superseded or conflict: it cites what a source said) a citation whose text was rewritten keeps
    its line and says which commit it was read at, instead of pointing at the corrected text."""
    notes = []

    def sub(m):
        end = s.find('"', m.end())
        tail = s[m.end():end if end >= 0 else len(s)]
        if re.search(r"\bat [0-9a-f]{7,}\b", tail):
            notes.append((m.group(1), 0, 0, "explicitly anchored"))
            return m.group(0)
        path, a = m.group(1), int(m.group(2))
        b = int(m.group(3) or a)
        if path not in files_old:
            files_old[path] = git_show(root, from_commit, path)
            try:
                files_new[path] = open("%s/%s" % (root, path), encoding="utf-8").read().split("\n")
            except OSError:
                files_new[path] = None
            if files_old[path] is not None and files_new[path] is not None:
                maps[path] = line_map(files_old[path], files_new[path])
        old, new = files_old.get(path), files_new.get(path)
        if old is None or new is None:
            notes.append((path, a, b, "file missing at one end"))
            return m.group(0)
        if old == new:
            return m.group(0)
        a2, b2, how = map_citation(old, new, maps[path], a, b)
        if a2 is None:
            notes.append((path, a, b, how))
            return m.group(0)
        notes.append((path, a, b, how))
        if historical and how == "rewritten in place":
            return m.group(0) + " (as read at %s)" % from_commit
        return "%s:%d" % (path, a2) + ("-%d" % b2 if m.group(3) else "")
    return CITE.sub(sub, s), notes

