          'level set at\n'
          '      bring-up from its own clean-air baseline, raises MASTER WARN and makes the sensor controller '
          'command the pack\n'
          "      gauge over the pack SMBus lead (J_SMB) to open both of the pack's protection FETs within 10 s of "
          'the reading\n'
          "      crossing its level: the gauge's SHUTDOWN where no input is present, and where one is (SHUTDOWN is "
          'entered only\n'
          '      with no charger present, SLUUAQ3A 5.4.2 and 13.1.8) its EMERGENCY SHUTDOWN through the Manual FET '
