         "      Board B's netlist and the assembly's lead table show slot 1's antenna lead to board A's J_RF3 with "
         'no active\n'
         "      element between the module and the jack, and slots 2 and 3's radios off from power-up; on the "
         "prototype the path's\n"
         "      loss from the module's U.FL to the jack is measured at 2.4 and 5 GHz and is not negative; no "
         'document claims the\n'
         "      module's approval holds through this path until Raspberry Pi's written position is held "
