          '    parent: NEED-15\n'
          '    statement: >-\n'
          '      Each board is built from its reviewed netlist and is fabricable and assemblable at its declared '
          'fabricator and\n'
          '      stack: its schematic is ERC-clean or explained, every pad carries a net or a declared no-connect, '
          'the board\n'
          '      matches its netlist, its stackup and layer count are declared and decided, its geometry, vias and '
          'planes are ones\n'
          '      the fabricator makes with nothing unrouted, and its fabrication, assembly and order sets are the '
          'current, complete\n'
          '      set with every applicable rule judged.\n'
          '    acceptance: >-\n'
          "      Each board's rule readings of SCH-001, SCH-002, SCH-005, STK-001, STK-002, RTE-001, RTE-002, "
          'VIA-001, VIA-002,\n'
