          'NOT_APPLICABLE at the phase\n'
          "      each rule applies to (rules_status), before that board's fabrication release.\n"
          '    allocated_to: [a, b, c, d, e, e5, p]\n'
          '    verification_method: [ERC, DRC, SCRIPT]\n'
          '    verification_phase: SCHEMATIC\n'
          '    final_phase: RELEASE_PACKAGE\n'
          '    prototype_1: core\n'
          '    prototype_1_basis: SESSION\n'
          '    prototype_1_choice: SC-04\n'
          '    prototype_1_why: >-\n'
          '      A condition of every core function, which runs on these boards: SC-04 puts a record under a need '
          'outside the core\n'
          '      in the core when it is a condition of a core function.\n'
          '    satisfied_by:\n'
          '      rules: [SCH-001, SCH-002, SCH-005, STK-001, STK-002, RTE-001, RTE-002, VIA-001, VIA-002, PLN-001, '
          'PLC-002, DFM-001, DFA-001, DOC-001, OUT-001, SGN-001]\n'
          '      decisions: []\n'
          '    rule_coverage: FULL\n'
          '    status: DEFINED\n'
          '    evidence_result: NOT_JUDGED\n'
          '    release_effect: BLOCKER\n'
          '    source: ["v2/ecad/tools/pcb_rules.yaml", "v2/docs/PCB-GOLDEN-RULES.md"]\n'
          '    source_check: VERIFIED\n'
          '    notes: >-\n'
          '      Created on 27 September 2026 by the layer-3 closer so that every BLOCKER or MUST_JUSTIFY rule of '
