 {'op': 'append_text',
  'section': 'records',
  'id': 'REQ-004',
  'field': 'notes',
  'base': '    notes: >-\n'
          '      D-01 names the IOHA tests A1 to A14 as core. A7 is traced by CON-004, A9 by CON-002, A10 by '
          'CON-003, A11 by\n'
          '      CHO-002 and A14 by REQ-031. The critical peripherals are every USB peripheral IOHA section 15 '
          'traces and the\n'
          '      kit-to-kit WiFi link; LoRa and cellular data are the named exceptions of SC-02 (ASM-001). '
          'FAILOVER-FABRIC.md\n'
          '      (26 September 2026) validates connectivity, direction, polarity, coupling and straps on a netlist, '
          'and nothing\n'
          '      that needs copper or silicon; its FAB-04 bears on A6 and A12 (CON-003) and FAB-02 on every module '
          'that is off\n'
          '      (CON-022). FEA-003 holds this record.',
  'add': "The bound is @SC:l2-delivery@'s (27 September 2026): until then the acceptance took its pass line from the "
         'per-device timeouts it would measure, which cannot fail. FEA-003 closing in failure would reopen this '
         "record's statement, not its bound.",
  'after': None},
 {'op': 'add_block',
  'section': 'records',
  'text': '  - id: @REQ:failover@\n'
          '    kind: requirement\n'
          '    parent: NEED-02\n'
          '    statement: >-\n'
          '      When the long-range bearer a message is queued for goes down, the kit hands the queue to another '
          'core long-range\n'
          '      bearer that is up, without operator action.\n'
          '    acceptance: >-\n'
          '      In the functional check, for each core long-range bearer (Iridium, 5G and APRS) in turn, with '
          'messages queued for\n'
          '      a correspondent another core long-range bearer reaches, the bearer disabled at the kit: it is '
          'declared down when\n'
          '      its device is lost, or when it has accepted no hand-off for 60 s while one is pending; its queue is '
          'handed to the\n'
          '      next long-range bearer that is up within 10 s of that; every queued message is delivered, the '
          'delivery times\n'
          '      recorded as characterisation (@SC:l2-delivery@).\n'
          '    allocated_to: [kit, sw]\n'
          '    verification_method: [PROTOTYPE_MEASUREMENT]\n'
          '    verification_phase: PROTOTYPE\n'
          '    prototype_1: core\n'
          '    prototype_1_basis: NEED_DEFAULT\n'
          '    satisfied_by:\n'
          '      rules: []\n'
          '      decisions: []\n'
          '    rule_coverage: NONE\n'
          '    rulings: [D-01]\n'
          '    choices: [@SC:l2-delivery@]\n'
          '    status: DEFINED\n'
          '    evidence_result: NOT_YET_TESTED\n'
          '    release_effect: BLOCKER\n'
          '    source: ["v2/docs/CONOPS.md section 4c", "owner ruling D-01", "session choice @SC:l2-delivery@"]\n'
          '    source_check: VERIFIED\n'
          '    notes: >-\n'
          '      Created on 27 September 2026 by the layer-3 closer: NEED-02 had no behavioural requirement that a '
          'queued message\n'
          '      reaches its correspondent over another bearer when one is down (the layer audit); its other records '
          'say each\n'
          '      bearer passes traffic (REQ-001) and how bearers are distributed (CON-001). The routing that picks '
          'the bearer is\n'
          "      the MeshSat Bridge's, specified outside this repository (CONOPS section 3, M1).",
  'fingerprint': 'When the long-range bearer a message is queued for goes down',
  'after': 'REQ-003'},
